create extension if not exists pgcrypto;
create table runs(id uuid primary key default gen_random_uuid(), params jsonb not null, status text not null default 'QUEUED', error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index one_active_run on runs ((true)) where status in ('QUEUED','RUNNING');
create table businesses(id uuid primary key default gen_random_uuid(),run_id uuid not null references runs,place_id text not null unique,identity_key text unique,name text not null,category text not null,source_urls jsonb not null default '[]',website_url text,email text,email_source text,brief jsonb,state text not null default 'DISCOVERED',failure_stage text,failure_reason text,created_at timestamptz default now());
create table audits(id uuid primary key default gen_random_uuid(),business_id uuid unique not null references businesses,score numeric,classification text not null,measurements jsonb,defects jsonb not null default '[]',screenshot_url text,created_at timestamptz default now());
create table opportunities(id uuid primary key default gen_random_uuid(),business_id uuid unique not null references businesses,website_opportunity numeric,quoted_price numeric,estimated_build_cost numeric,research_cost numeric,purchase_probability numeric,expected_contribution numeric,priority numeric);
create table sites(id uuid primary key default gen_random_uuid(),business_id uuid unique not null references businesses,lovable_project_id text,preview_url text,screenshot_url text,zip_path text,checksum text,qa_status text not null default 'PENDING',build_log text,created_at timestamptz default now());
create table products(id uuid primary key default gen_random_uuid(),site_id uuid unique not null references sites,whop_product_id text unique,whop_plan_id text unique,storefront_url text,purchase_url text,amount numeric not null,currency text default 'usd',verified boolean not null default false);
create table emails(id uuid primary key default gen_random_uuid(),business_id uuid unique references businesses,address text not null,provider_message_id text,status text not null default 'PENDING',sent_at timestamptz,opted_out boolean not null default false);
create table orders(id uuid primary key default gen_random_uuid(),whop_payment_id text unique not null,whop_event_id text unique not null,product_id uuid not null references products,buyer_email text not null,amount numeric not null,currency text not null,internal boolean not null default false,paid_at timestamptz default now(),delivery_state text not null default 'PENDING',delivery_message_id text,delivery_claimed_at timestamptz,delivery_attempts integer not null default 0,delivery_generation integer not null default 1,next_attempt_at timestamptz default now(),download_token_hash text,download_expires_at timestamptz,error text);
create table events(id uuid primary key default gen_random_uuid(),run_id uuid references runs,business_id uuid references businesses,created_at timestamptz not null default now(),action text not null,reason text not null,cost_usd numeric not null default 0,cost_kind text not null default 'estimate');
create or replace function claim_run() returns setof runs language plpgsql security definer set search_path=public as $$ begin return query update runs set status='RUNNING',updated_at=now() where id=(select id from runs where status='QUEUED' order by created_at for update skip locked limit 1) returning *; end $$;
create or replace function reserve_cost(p_run uuid,p_business uuid,p_action text,p_cost numeric) returns boolean language plpgsql security definer set search_path=public as $$ declare cap numeric; spent numeric; begin select (params->>'maxEstimatedRunCostUsd')::numeric into cap from runs where id=p_run for update;select coalesce(sum(cost_usd),0) into spent from events where run_id=p_run;if p_cost<0 or spent+p_cost>cap then return false;end if;insert into events(run_id,business_id,action,reason,cost_usd) values(p_run,p_business,p_action,'Reserved provider cost estimate',p_cost);return true;end $$;
-- Service-role only: no dashboard database credentials are exposed to browsers.
do $$ declare t text; begin foreach t in array array['runs','businesses','audits','opportunities','sites','products','emails','orders','events'] loop execute format('alter table %I enable row level security',t);end loop;end $$;
revoke execute on function claim_run() from public,anon,authenticated;
revoke execute on function reserve_cost(uuid,uuid,text,numeric) from public,anon,authenticated;
grant execute on function claim_run() to service_role;
grant execute on function reserve_cost(uuid,uuid,text,numeric) to service_role;
insert into storage.buckets(id,name,public) values('website-zips','website-zips',false),('website-media','website-media',true) on conflict(id) do nothing;
